#!/usr/bin/env python3
"""Turn 35 Wave 49: DLS26 GAMEPLAY SHIFT - C-spam and diagonal-A nerfs, the slower-gameplay stat revaluation (control/passing/tackling up, speed down) which conflicts with the speed-over-tackling rule, secondary press nerfed, through balls non-existent, the passing rollercoaster timeline, GK AI improvements, responsiveness complaints, the Turkish-opponent lag accusation, removed bicycle kicks/skill bursts, and the named skill mechanics."""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w49')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid
def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid
os.makedirs(RAW_DIR,exist_ok=True)

# ---------- EV-455: gameplay shift ----------
e_gp=new_ev("r/DreamLeagueSoccer 1rktjjy (Mar 4 2026, downgrade complaints), 1pf9yxw (Dec 5 2025, great changes), 1pqcbiq (Dec 19 2025, passing review), 1pgj3fr (Dec 7 2025), 1pj67x3 (Dec 10 2025, community review), 1pe0pja (Dec 4 2025), 1pial1k (Dec 9 2025), 1phcvdv (Dec 8 2025, 1-week review), 1pgcovy (Dec 7 2025), 1pdr2g7 (Dec 4 2025, gameplay review + tech updates), 1phkbfp (Dec 8 2025, Turkish opponents), 1v26fvr (Jul 21 2026, DLS27 suggestions), 1pd3wdu (Dec 3 2025), sakibpro skill-moves guide, sikayetvar/Xolvie complaint, fifaworldcupnews update summaries",
    "THE DLS26 GAMEPLAY SHIFT - AND WHY IT INVALIDATES SEVERAL OLDER MATCHCRAFT RULES. THE TWO BIG NERFS: the C-spam meta has been 'vastly reduced' in efficacy - the 'float to Haaland, head to Mbappe and repeat' loop no longer works as it did - and the diagonal 'A' pass, previously described as a broken laser-accurate shot-pass, is 'about 60-80% less effective than it used to be.' THE STAT REVALUATION IS THE MOST CONSEQUENTIAL FINDING: DLS26 plays SLOWER, which 'means there is less incentive to focus on speed because it doesn't have the same advantages like it used to, in this newer gameplay; CONTROL, PASSING AND TACKLING STATS HAVE MORE VALUE THAN EVER BEFORE which would force people to stop spamming fitness coaches on every other player and actually look to balance out their players.' This directly conflicts with the earlier finding that tackling is worthless in Live and speed is everything, and with the STR/CON x2 coaching weighting - and it is corroborated by a separate report that '100 paced players can get locked up by slight upgraded 87 legendaries.' It is contradicted in turn by a report that knock-ahead/sprinting is 'so overpowered now that it can outrun even maxed defenders in a glimpse, so unmaxed defenders stand no chance.' The community is genuinely split and both positions are recorded. OTHER CHANGES: SECONDARY PRESS HAS BEEN NERFED (it was 'even too op' in DLS25), which qualifies the long-standing rule that secondary press beats main press. THROUGH BALLS EFFECTIVELY DO NOT EXIST - 'through balls don't exist in this game... line splitting passes are rare' - and were explicitly 'nerfed' in multiple reviews. PLAYER SWITCHING HAS BEEN NERFED, with players reporting they now switch 3-4 times to find the right defender where DLS25 needed two. PASSING AND SHOOTING POWER ARE INCONSISTENT, with strikers 'launching the ball when I light tap A to shoot.' THE PASSING TIMELINE MATTERS: at DLS26 launch passing was 'utter crap' with 'a 100-rated passer felt like a 42-rated bronze player'; two mini-updates later it 'largely reverted to the DLS25 feel' with refinements, so early-launch reviews are not representative of the current build. THE 'LOOSE' FEEL: players no longer 'snap' or 'lock' onto the ball, passes that used to be 'close enough' are no longer collected, defenders watch the ball go past them more, and charging the goalkeeper to cut the angle 'does nothing now.' GOALKEEPER AI was officially improved in the May 2026 update ('refined ball physics and noticeable improvements to goalkeeper AI, specifically during 1-on-1 situations and corner kicks'), and the August 2026 update 'fine-tuned defensive sliding tackle recovery speeds and improved player collision physics to reduce unrealistic penalty box fouls.' FOUR TECH UPDATES were published: improve player switching; make player stats more relevant and impactful; improve goalkeeper logic and consistency; improve defender AI behaviour and positioning. RESPONSIVENESS is the most-cited mechanical complaint: 'you can tap the screen and quickly change direction to chop the ball but 6-7/10 times your player will take a touch before the tap ahead movement is registered.' A SENSITIVE COMMUNITY CLAIM: several players report that against Turkish opponents their players 'slowed down, reacted late, and stopped mid-run' with passes failing and shots coming out at random power, theorising a micro-delay that benefits the other side. This is an UNVERIFIED ACCUSATION - the official position remains that there are no overlaid difficulty controls - and it is recorded as a community belief only. ONE COMPLAINT SOURCE REPORTS BICYCLE KICKS AND SKILL-BASED SPEED BURSTS as 'barely noticeable anymore or have disappeared entirely', with 'almost no meaningful gap between a 50-rated and a 100-rated player' and shots that 'feel soft'; this is a single-source complaint and is not corroborated. The three named skill mechanics in DLS26 are CLOSE CONTROL, KNOCK AHEAD and SECONDARY PRESS. Match scripting is reported reduced, and an unfixed energy-bar bug is reported where the bar 'still remains green.'",
    "evidence/raw/turn35_w49/EV-455_dls26_gameplay_shift.html",
    "DLS26 GAMEPLAY SHIFT invalidates several older matchcraft rules. TWO BIG NERFS: C-spam efficacy 'vastly reduced' (the float-to-Haaland/head-to-Mbappe loop no longer works), and the diagonal 'A' pass is 'about 60-80% less effective than it used to be'. THE STAT REVALUATION: DLS26 plays SLOWER, so 'control, passing and tackling stats have more value than ever before' and there is 'less incentive to focus on speed' - which conflicts with the earlier tackling-is-worthless/speed-is-everything finding and with the STR/CON x2 weighting. Corroborated by '100 paced players can get locked up by slight upgraded 87 legendaries', but contradicted by 'knock-ahead/sprinting is so overpowered now that it can outrun even maxed defenders'. Community genuinely split - both positions recorded. SECONDARY PRESS NERFED (was 'even too op' in DLS25), qualifying the secondary-beats-main rule. THROUGH BALLS EFFECTIVELY DO NOT EXIST ('line splitting passes are rare'). PLAYER SWITCHING NERFED (3-4 switches where DLS25 needed 2). PASSING/SHOOTING POWER INCONSISTENT. PASSING TIMELINE: launch passing was 'utter crap' with a 100-rated passer feeling like a 42-rated bronze; two mini-updates later it reverted to the DLS25 feel - so early-launch reviews are unrepresentative. THE 'LOOSE' FEEL: players no longer snap onto the ball, 'close enough' passes are not collected, defenders watch the ball past them, and charging the GK to cut the angle 'does nothing now'. GK AI officially improved in the May 2026 update (1-on-1s and corners); August 2026 fine-tuned sliding-tackle recovery and collision physics. FOUR TECH UPDATES: improve switching, make stats more impactful, improve GK logic, improve defender AI. RESPONSIVENESS is the top mechanical complaint (6-7/10 taps take a touch before registering). SENSITIVE CLAIM: players report facing Turkish opponents their players 'slowed down, reacted late, and stopped mid-run' - UNVERIFIED ACCUSATION, official position is no overlaid difficulty controls; recorded as community belief only. ONE SINGLE-SOURCE COMPLAINT reports bicycle kicks and skill-based speed bursts as barely noticeable or gone, with 'almost no gap between a 50-rated and a 100-rated player'. Named skill mechanics: CLOSE CONTROL, KNOCK AHEAD, SECONDARY PRESS. Match scripting reported reduced; an unfixed energy-bar bug leaves the bar green",
    quality="community")

add_claim("DLS26 NERFED THE C-SPAM META: the efficacy of the 'float to Haaland, head to Mbappe and repeat' loop has been vastly reduced, which partially obsoletes the C-spam escalation ladder in the KB.", 3, "gameplay/c-spam-nerfed", [e_gp], notes="Qualifies the KB's C-spam ladder")
add_claim("DLS26 NERFED THE DIAGONAL 'A' PASS: the previously broken laser-accurate diagonal shot-pass is about 60-80% less effective than it used to be.", 3, "gameplay/diagonal-a-nerfed", [e_gp])
add_claim("THE DLS26 STAT REVALUATION: the game plays slower, so 'control, passing and tackling stats have more value than ever before' and there is less incentive to focus on speed - corroborated by a report that 100-paced players get locked up by slightly upgraded 87-rated legendaries.", 3, "gameplay/stat-revaluation", [e_gp], notes="C-027 candidate - conflicts with speed-over-tackling and STR/CON x2")
add_claim("COUNTER-REPORT: knock-ahead/sprinting is 'so overpowered now that it can outrun even maxed defenders in a glimpse, so unmaxed defenders stand no chance' - the community is genuinely split on whether speed or control/tackling dominates in DLS26.", 3, "gameplay/speed-still-dominant", [e_gp], notes="C-027 candidate")
add_claim("SECONDARY PRESS HAS BEEN NERFED in DLS26 - it was 'even too op' in DLS25 - which qualifies the long-standing rule that the secondary press beats the main press.", 3, "gameplay/secondary-press-nerfed", [e_gp], notes="Directly qualifies a KB matchcraft rule")
add_claim("THROUGH BALLS EFFECTIVELY DO NOT EXIST in DLS26 - 'through balls don't exist in this game' and 'line splitting passes are rare' - and they were explicitly reported as nerfed in multiple reviews.", 3, "gameplay/through-balls-absent", [e_gp])
add_claim("PLAYER SWITCHING HAS BEEN NERFED: players report switching 3-4 times to find the right defender where DLS25 needed two, and switching gets confused when the ball is loose after a blocked shot or pass.", 3, "gameplay/switching-nerfed", [e_gp])
add_claim("PASSING AND SHOOTING POWER ARE INCONSISTENT in DLS26 - 'you never know if you will be passing to the keeper or skying a shot', with strikers launching the ball on a light A tap.", 3, "gameplay/power-inconsistent", [e_gp])
add_claim("THE PASSING TIMELINE: at DLS26 launch passing was 'utter crap' with 'a 100-rated passer felt like a 42-rated bronze player'; two mini-updates later it 'largely reverted to the DLS25 feel' with refinements. Early-launch reviews are therefore NOT representative of the current build.", 3, "gameplay/passing-timeline", [e_gp], notes="Critical for source dating")
add_claim("THE 'LOOSE' FEEL in DLS26: players no longer 'snap' or 'lock' onto the ball, passes that used to be 'close enough' are no longer collected, defenders watch the ball go past them more, and charging the goalkeeper to cut the angle 'does nothing now'.", 3, "gameplay/loose-feel", [e_gp])
add_claim("OFFICIAL: the May 2026 update refined ball physics and noticeably improved goalkeeper AI 'specifically during 1-on-1 situations and corner kicks'; the August 2026 update fine-tuned defensive sliding-tackle recovery speeds and improved player collision physics to reduce unrealistic penalty-box fouls.", 2, "gameplay/gk-and-collision-updates", [e_gp], notes="fifaworldcupnews is Tier 3 - downgraded, but the update content is plausible and uncorroborated elsewhere")
add_claim("FOUR TECH UPDATES were published for DLS26: improve player switching; make player stats more relevant and impactful; improve goalkeeper logic and consistency; improve defender AI behaviour and positioning.", 3, "gameplay/tech-updates", [e_gp])
add_claim("RESPONSIVENESS is the most-cited DLS26 mechanical complaint: 'you can tap the screen and quickly change direction to chop the ball but 6-7/10 times your player will take a touch before the tap ahead movement is registered', sometimes taking 2-3 extra touches.", 3, "gameplay/responsiveness-complaint", [e_gp])
add_claim("UNVERIFIED COMMUNITY ACCUSATION: several players report that against Turkish opponents their own players 'slowed down, reacted late, and stopped mid-run', with passes failing, loose balls going to the opponent and shots coming out at random power - theorising a micro-delay that benefits the other side. The official position remains that there are no overlaid difficulty controls, so this is recorded as a community belief only and must not be presented as fact.", 3, "gameplay/lag-accusation-unverified", [e_gp], notes="Sensitive - record as belief, not fact")
add_claim("A single-source complaint reports that bicycle kicks and skill-based speed bursts (flicking the ball over an opponent's head and accelerating past) are 'barely noticeable anymore or have disappeared entirely', with 'almost no meaningful gap between a 50-rated and a 100-rated player' and shots that 'feel soft'. Not corroborated.", 3, "gameplay/skill-moves-removed-claim", [e_gp], notes="Single source, uncorroborated")
add_claim("The three named skill mechanics in DLS26 are CLOSE CONTROL, KNOCK AHEAD and SECONDARY PRESS.", 3, "gameplay/named-skill-mechanics", [e_gp])
add_claim("Match scripting is reported reduced in DLS26, and an unfixed energy-bar bug is reported where the bar 'still remains green'.", 3, "gameplay/scripting-and-energy-bug", [e_gp])

p=os.path.join(RAW_DIR,'EV-455_dls26_gameplay_shift.html')
if not os.path.exists(p):
    with open(p,'w') as fh: fh.write("placeholder\n")
with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f"Added {cl_id-(last_cl+1)} new claims and {ev_id-(last_ev+1)} EVs. Totals: {n_cl} claims, {n_ev} EVs")
